mapper.select:
SELECT CASE WHEN EXISTS (
    SELECT 1
    FROM effective_attendance_event event
    JOIN employee roster_employee
      ON roster_employee.employee_id = event.employee_id
     AND roster_employee.company_id = #{companyId}
    WHERE event.created_at <= #{dataAsOf}
      AND (
            (
                event.event_kind = 'PUNCH_POINT'
                AND event.point_instant >= #{periodStart}
                AND event.point_instant < #{periodEndExclusive}
            )
            OR (
                event.event_kind = 'OA_INTERVAL'
                AND event.interval_end > #{periodStart}
                AND event.interval_start < #{periodEndExclusive}
            )
          )
) THEN 1 ELSE 0 END AS hasEvidence

SELECT #{organizationId}
UNION
SELECT closure.descendant_organization_id
FROM organization_current_closure closure
WHERE closure.ancestor_organization_id = #{organizationId}

SELECT employee.employee_id AS employeeId,
       employee_version.employee_number AS employeeNumber,
       employee_version.display_name AS employeeName,
       employment.organization_id AS organizationId,
       organization_version.name AS organizationName
FROM employee employee
JOIN employee_version employee_version
  ON employee_version.employee_id = employee.employee_id
 AND employee_version.status = 'ACTIVE'
 AND employee_version.effective_from <= #{asOf}
 AND (
        employee_version.effective_to IS NULL
        OR employee_version.effective_to > #{asOf}
 )
JOIN employment_assignment employment
  ON employment.employee_id = employee.employee_id
 AND employment.version_valid_to IS NULL
 AND employment.record_status = 'ACTIVE'
 AND employment.effective_from <= #{asOf}
 AND (
        employment.effective_to IS NULL
        OR employment.effective_to > #{asOf}
 )
JOIN organization_version organization_version
  ON organization_version.organization_id = employment.organization_id
 AND organization_version.status = 'ACTIVE'
 AND organization_version.effective_from <= #{asOf}
 AND (
        organization_version.effective_to IS NULL
        OR organization_version.effective_to > #{asOf}
 )
WHERE employee.company_id = #{companyId}

      AND employee.employee_id IN

          #{id}



      AND employment.organization_id IN

          #{id}


ORDER BY employee_version.employee_number
LIMIT 2000

SELECT COUNT(*)
FROM attendance_report_exception_fact fact
JOIN employee_version employee_version
  ON employee_version.employee_version_id = fact.employee_version_id
WHERE 
  AND fact.business_date >= #{fromDate}
  AND fact.business_date < #{toDateExclusive}



      AND fact.severity = #{severity}


      AND fact.state = #{state}

SELECT fact.exception_case_id AS caseId, fact.employee_id AS employeeId, employee_version.employee_number AS employeeNumber, employee_version.display_name AS employeeName, fact.organization_id AS organizationId, organization_version.name AS organizationName, fact.business_date AS businessDate, fact.exception_type AS exceptionType, fact.severity, fact.state, fact.exception_minutes AS exceptionMinutes, fact.safe_evidence_summary AS details, daily.first_punch_at AS firstPunchAt, daily.last_punch_at AS lastPunchAt FROM attendance_report_exception_fact fact JOIN employee_version employee_version ON employee_version.employee_version_id = fact.employee_version_id JOIN organization_version organization_version ON organization_version.organization_version_id = fact.organization_version_id LEFT JOIN ( SELECT daily_fact.attendance_report_projection_id, daily_fact.employee_id, daily_fact.business_date, MIN(daily_fact.first_punch_at) AS first_punch_at, MAX(daily_fact.last_punch_at) AS last_punch_at FROM attendance_report_daily_fact daily_fact WHERE daily_fact.attendance_report_projection_id IN
#{id}
GROUP BY daily_fact.attendance_report_projection_id, daily_fact.employee_id, daily_fact.business_date ) daily ON daily.attendance_report_projection_id = fact.attendance_report_projection_id AND daily.employee_id = fact.employee_id AND daily.business_date = fact.business_date WHERE AND fact.business_date >= #{fromDate} AND fact.business_date < #{toDateExclusive}
AND fact.severity = #{severity}
AND fact.state = #{state}
ORDER BY fact.business_date, employee_version.employee_number, fact.exception_case_id LIMIT #{limit} OFFSET #{offset}

SELECT COUNT(*)
FROM attendance_report_oa_fact fact
JOIN employee_version employee_version
  ON employee_version.employee_version_id = fact.employee_version_id



WHERE 
  AND COALESCE(fact.interval_end, fact.point_instant)
        > #{fromDate}
  AND COALESCE(fact.interval_start, fact.point_instant)
        < #{toDateExclusive}



      AND (
            fact.leave_type_code = #{leaveType}
            OR (#{leaveType} = 'COMPENSATORY'
                AND fact.document_type = 'TIME_OFF')
      )


      AND fact.source_status = #{sourceStatus}



      AND DAY(COALESCE(fact.interval_start, fact.point_instant))
            = #{occurrenceDay}

SELECT fact.oa_attendance_document_id AS documentId, fact.employee_id AS employeeId, employee_version.employee_number AS employeeNumber, employee_version.display_name AS employeeName, fact.organization_id AS organizationId, organization_version.name AS organizationName, fact.document_type AS documentType, COALESCE( NULLIF(fact.leave_type_code, ''), context.overtime_type, CASE WHEN fact.document_type = 'TIME_OFF' THEN 'TIME_OFF' END) AS leaveType, COALESCE(fact.interval_start, fact.point_instant) AS startAt, COALESCE(fact.interval_end, TIMESTAMPADD(MICROSECOND, 1, fact.point_instant)) AS endExclusive, fact.recognized_minutes AS recognizedMinutes, fact.source_status AS sourceStatus, CASE WHEN document.source_business_key LIKE 'PAPER:%' THEN 'PAPER' ELSE 'OA' END AS sourceOrigin FROM attendance_report_oa_fact fact LEFT JOIN oa_attendance_document document ON document.oa_attendance_document_id = fact.oa_attendance_document_id JOIN employee_version employee_version ON employee_version.employee_version_id = fact.employee_version_id JOIN organization_version organization_version ON organization_version.organization_version_id = fact.organization_version_id
WHERE AND COALESCE(fact.interval_end, fact.point_instant) > #{fromDate} AND COALESCE(fact.interval_start, fact.point_instant) < #{toDateExclusive}
AND ( fact.leave_type_code = #{leaveType} OR (#{leaveType} = 'COMPENSATORY' AND fact.document_type = 'TIME_OFF') )
AND fact.source_status = #{sourceStatus}
AND DAY(COALESCE(fact.interval_start, fact.point_instant)) = #{occurrenceDay}
ORDER BY COALESCE(fact.interval_start, fact.point_instant), employee_version.employee_number LIMIT #{limit} OFFSET #{offset}

SELECT COUNT(*) FROM ( SELECT fact.employee_id FROM attendance_report_daily_fact fact JOIN employee_version employee_version ON employee_version.employee_version_id = fact.employee_version_id WHERE AND fact.business_date >= #{fromDate} AND fact.business_date < #{toDateExclusive}
GROUP BY fact.employee_id HAVING 1 = 1
AND SUM(fact.late_minutes) > 0
) aggregated

SELECT fact.employee_id AS employeeId, MAX(employee_version.employee_number) AS employeeNumber, MAX(employee_version.display_name) AS employeeName, MAX(fact.organization_id) AS organizationId, MAX(organization_version.name) AS organizationName, SUM(CASE WHEN fact.late_minutes > 0 THEN 1 ELSE 0 END) AS lateEvents, SUM(fact.late_minutes) AS lateMinutes, SUM(fact.penalized_late_minutes) AS penalizedLateMinutes, SUM(fact.missing_punch_count) AS missingPunches, SUM(fact.scheduled_minutes) AS scheduledMinutes, SUM(fact.paid_overtime_minutes) AS paidOvertimeMinutes, SUM(fact.compensatory_overtime_minutes) AS compensatoryOvertimeMinutes, SUM(fact.voluntary_overtime_minutes) AS voluntaryOvertimeMinutes, SUM(fact.leave_or_time_off_minutes) AS leaveMinutes, SUM(CASE WHEN fact.leave_type IN ('ANNUAL', 'ANNUAL_LEAVE') THEN fact.leave_or_time_off_minutes ELSE 0 END) AS annualLeaveMinutes, SUM(CASE WHEN fact.leave_type IN ( 'TIME_OFF', 'COMPENSATORY') THEN fact.leave_or_time_off_minutes ELSE 0 END) AS timeOffMinutes, SUM(fact.actual_work_minutes) AS actualWorkMinutes, SUM(fact.scheduled_attendance_days) AS scheduledAttendanceDays, SUM(fact.actual_attendance_days) AS actualAttendanceDays, CAST(NULL AS CHAR) AS employmentNote FROM attendance_report_daily_fact fact JOIN employee_version employee_version ON employee_version.employee_version_id = fact.employee_version_id JOIN organization_version organization_version ON organization_version.organization_version_id = fact.organization_version_id WHERE AND fact.business_date >= #{fromDate} AND fact.business_date < #{toDateExclusive}
GROUP BY fact.employee_id HAVING 1 = 1
AND SUM(fact.late_minutes) > 0
ORDER BY MAX(employee_version.employee_number) LIMIT #{limit} OFFSET #{offset}

SELECT fact.employee_id AS employeeId, fact.business_date AS businessDate, fact.day_type AS dayType, fact.leave_type AS leaveType, fact.late_minutes AS lateMinutes, fact.early_departure_minutes AS earlyDepartureMinutes, fact.missing_punch_count AS missingPunchCount, fact.first_punch_at AS firstPunchAt, fact.last_punch_at AS lastPunchAt, fact.paid_overtime_minutes AS paidOvertimeMinutes, fact.compensatory_overtime_minutes AS compensatoryOvertimeMinutes FROM attendance_report_daily_fact fact WHERE AND fact.business_date >= #{fromDate} AND fact.business_date < #{toDateExclusive} AND fact.employee_id IN
#{id}
ORDER BY fact.employee_id, fact.business_date

SELECT COUNT(*) FROM ( SELECT fact.employee_id, AS leaveType FROM attendance_report_oa_fact fact JOIN employee_version employee_version ON employee_version.employee_version_id = fact.employee_version_id WHERE AND fact.document_type IN ('LEAVE', 'TIME_OFF') AND COALESCE(fact.interval_end, fact.point_instant) > #{fromDate} AND COALESCE(fact.interval_start, fact.point_instant) < #{toDateExclusive}
AND ( fact.leave_type_code = #{leaveType} OR (#{leaveType} = 'COMPENSATORY' AND fact.document_type = 'TIME_OFF') )
GROUP BY fact.employee_id, leaveType ) summarized

SELECT fact.employee_id AS employeeId, MAX(employee_version.employee_number) AS employeeNumber, MAX(employee_version.display_name) AS employeeName, MAX(fact.organization_id) AS organizationId, MAX(organization_version.name) AS organizationName, AS leaveType, SUM(fact.recognized_minutes) AS recognizedMinutes, COUNT(*) AS documentCount FROM attendance_report_oa_fact fact JOIN employee_version employee_version ON employee_version.employee_version_id = fact.employee_version_id JOIN organization_version organization_version ON organization_version.organization_version_id = fact.organization_version_id WHERE AND fact.document_type IN ('LEAVE', 'TIME_OFF') AND COALESCE(fact.interval_end, fact.point_instant) > #{fromDate} AND COALESCE(fact.interval_start, fact.point_instant) < #{toDateExclusive}
AND ( fact.leave_type_code = #{leaveType} OR (#{leaveType} = 'COMPENSATORY' AND fact.document_type = 'TIME_OFF') )
GROUP BY fact.employee_id, leaveType ORDER BY MAX(employee_version.employee_number), leaveType LIMIT #{limit} OFFSET #{offset}


  AND fact.recognized_overtime_minutes > 0

ORDER BY employee_version.employee_number, fact.business_date
LIMIT #{limit} OFFSET #{offset}

