AND fact.business_date >= #{fromDate}
AND fact.business_date < #{toDateExclusive}
AND fact.recognized_overtime_minutes > 0


  AND DAY(fact.business_date) = #{occurrenceDay}


  AND EXISTS (
      SELECT 1
      FROM attendance_report_daily_fact bucket
      WHERE bucket.attendance_report_projection_id =
            fact.attendance_report_projection_id
        AND bucket.employee_id = fact.employee_id
        AND bucket.business_date >= #{fromDate}
        AND bucket.business_date < #{toDateExclusive}
        AND bucket.recognized_overtime_minutes > 0
        AND bucket.day_type IN (
            'WEEKDAY', 'WORKDAY', 'WORKING_DAY', 'ADJUSTED_WORKDAY')
  )


  AND EXISTS (
      SELECT 1
      FROM attendance_report_daily_fact bucket
      WHERE bucket.attendance_report_projection_id =
            fact.attendance_report_projection_id
        AND bucket.employee_id = fact.employee_id
        AND bucket.business_date >= #{fromDate}
        AND bucket.business_date < #{toDateExclusive}
        AND bucket.recognized_overtime_minutes > 0
        AND bucket.day_type IN ('SATURDAY', 'SUNDAY')
  )



  AND EXISTS (
      SELECT 1
      FROM attendance_report_daily_fact bucket
      WHERE bucket.attendance_report_projection_id =
            fact.attendance_report_projection_id
        AND bucket.employee_id = fact.employee_id
        AND bucket.business_date >= #{fromDate}
        AND bucket.business_date < #{toDateExclusive}
        AND bucket.recognized_overtime_minutes > 0
        AND bucket.day_type IN ('PUBLIC_HOLIDAY', 'HOLIDAY')
  )

